package com.justjava.humanresource.employeeexit.service;
import com.justjava.humanresource.aau.keycloak.KeycloakAdminService; import com.justjava.humanresource.employeeexit.entity.*; import com.justjava.humanresource.employeeexit.repository.*; import com.justjava.humanresource.hr.repository.EmployeeRepository; import lombok.RequiredArgsConstructor; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.LocalDateTime;
@Service @RequiredArgsConstructor public class ExitAccessDeprovisioningService {
 private final EmployeeExitService exitService; private final EmployeeExitCaseRepository exits; private final ExitAccessActionRepository actions; private final EmployeeRepository employees; private final KeycloakAdminService keycloak;
 @Value("${keycloak.realm}") private String realm;
 @Transactional public void revokeKeycloak(Long exitId){EmployeeExitCase x=exitService.require(exitId);var employee=employees.findById(x.getEmployeeId()).orElseThrow();ExitAccessAction action=actions.findByExitCaseIdAndSystemName(exitId,"KEYCLOAK").orElseGet(()->{ExitAccessAction a=new ExitAccessAction();a.setExitCaseId(exitId);a.setSystemName("KEYCLOAK");a.setExternalIdentity(employee.getKeycloakUserId());a.setScheduledAt(LocalDateTime.now());return actions.save(a);});if("COMPLETED".equals(action.getStatus()))return;action.setAttemptCount(action.getAttemptCount()+1);if(employee.getKeycloakUserId()!=null&&!employee.getKeycloakUserId().isBlank())keycloak.disableUser(realm,employee.getKeycloakUserId());action.setStatus("COMPLETED");action.setCompletedAt(LocalDateTime.now());action.setLastError(null);actions.save(action);x.setAccessRevokedAt(LocalDateTime.now());exits.save(x);}
}
